CREATE TABLE `cctv_report_details` (
  `id` int NOT NULL AUTO_INCREMENT,
  `report_id` int NOT NULL,
  `nvr_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `online_channels` int NOT NULL,
  `total_channels` int NOT NULL DEFAULT '0',
  `channel_statuses_json` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `report_id` (`report_id`),
  CONSTRAINT `cctv_report_details_ibfk_1` FOREIGN KEY (`report_id`) REFERENCES `cctv_reports` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
