DROP TABLE IF EXISTS `cctv_reports`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cctv_reports` (
  `id` int NOT NULL AUTO_INCREMENT,
  `building` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `report_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `total_channels` int NOT NULL,
  `online_channels` int NOT NULL,
  `offline_channels` int NOT NULL,
  `online_percentage` float NOT NULL,
  `submitted_by_id` int DEFAULT NULL,
  `submission_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_deleted` tinyint(1) DEFAULT '0',
  `deleted_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `updated_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cctv_reports_building` (`building`),
  KEY `idx_cctv_reports_report_time` (`report_time`),
  KEY `idx_cctv_reports_submitted_by` (`submitted_by_id`),
  KEY `idx_cctv_reports_building_time` (`building`,`report_time`),
  CONSTRAINT `cctv_reports_ibfk_1` FOREIGN KEY (`submitted_by_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
