  `zone5_status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `zone6_status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `submitted_by_id` int DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `is_deleted` tinyint(1) DEFAULT '0',
